def install_guards() -> None:
    op.execute("INSERT INTO write_gate (id) VALUES (1)")
    for table in IMMUTABLE:
        for operation in ("UPDATE", "DELETE"):
            op.execute(
                f"CREATE TRIGGER immutable_{table}_{operation.lower()} "
                f"BEFORE {operation} ON {table} "
                "BEGIN SELECT RAISE(ABORT, 'append-only record'); END"
            )
    op.execute("""CREATE TRIGGER pinned_session BEFORE UPDATE OF id, learner_id, lesson_version_id,
        idempotency_key, created_at ON learning_sessions
        BEGIN SELECT RAISE(ABORT, 'session identity/version is immutable'); END""")
    op.execute("""CREATE TRIGGER session_transition BEFORE UPDATE OF state ON learning_sessions
        WHEN NOT (NEW.state = OLD.state OR
          (OLD.state = 'awaiting_prediction' AND NEW.state = 'ready_for_attempt') OR
          (OLD.state = 'ready_for_attempt' AND NEW.state = 'verification_pending') OR
          (OLD.state = 'verification_pending' AND NEW.state IN ('needs_revision','completed')) OR
          (OLD.state = 'needs_revision' AND NEW.state = 'verification_pending') OR
          (OLD.state NOT IN ('completed','abandoned') AND NEW.state = 'abandoned'))
        BEGIN SELECT RAISE(ABORT, 'invalid session transition'); END""")
    op.execute("""CREATE TRIGGER finalize_run_once BEFORE UPDATE ON verification_runs
        WHEN OLD.status != 'pending' OR NEW.status NOT IN ('passed','failed','error') OR
          NEW.id != OLD.id OR NEW.session_id != OLD.session_id OR
          NEW.attempt_id != OLD.attempt_id OR NEW.idempotency_key != OLD.idempotency_key OR
          NEW.created_at != OLD.created_at
        BEGIN SELECT RAISE(ABORT, 'verification result is immutable'); END""")
    op.execute("""CREATE TRIGGER preserve_runs BEFORE DELETE ON verification_runs
        BEGIN SELECT RAISE(ABORT, 'verification history is append-only'); END""")
    op.execute("""CREATE TRIGGER checks_before_finalization BEFORE INSERT ON verification_checks
        WHEN NOT EXISTS (SELECT 1 FROM verification_runs
          WHERE id = NEW.run_id AND status = 'pending')
        BEGIN SELECT RAISE(ABORT, 'checks require pending run'); END""")
    op.execute("""CREATE TRIGGER verified_run BEFORE UPDATE OF status ON verification_runs
        WHEN NEW.status = 'passed' AND
          (SELECT COUNT(*) FROM verification_checks WHERE run_id = NEW.id AND matched = 1
            AND code IN ('http_status','api_response','validation',
                         'row_count','stored_values')) != 5
        BEGIN SELECT RAISE(ABORT, 'successful verification requires all observed checks'); END""")
    op.execute("""CREATE TRIGGER completion_evidence BEFORE UPDATE OF state ON learning_sessions
        WHEN NEW.state = 'completed' AND NOT EXISTS
          (SELECT 1 FROM verification_runs WHERE session_id = NEW.id AND status = 'passed')
        BEGIN SELECT RAISE(ABORT, 'completion requires successful verification'); END""")


def remove_guards() -> None:
    for table in IMMUTABLE:
        for operation in ("update", "delete"):
            op.execute(f"DROP TRIGGER immutable_{table}_{operation}")
    for name in (
        "pinned_session",
        "session_transition",
        "finalize_run_once",
        "preserve_runs",
        "checks_before_finalization",
        "verified_run",
        "completion_evidence",
    ):
        op.execute(f"DROP TRIGGER {name}")


